package com.internhub.entity;
import jakarta.validation.constraints.DecimalMin; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.DBRef; import org.springframework.data.mongodb.core.mapping.Document;
import java.math.BigDecimal; import java.time.Instant; import java.time.LocalDate; import java.util.ArrayList; import java.util.List;
@Document("internships") @CompoundIndex(name="status_company_idx", def="{'status': 1, 'companyId': 1}") public class Internship {
 @Id private Long id; @Indexed private Long companyId; @DBRef private CompanyProfile company; @NotBlank @Size(max=180) private String title; @NotBlank private String description; private String location; private String workMode; private String duration; @DecimalMin("0.0") private BigDecimal stipendAmount; private String stipendCurrency; private List<String> skills=new ArrayList<>(); private String eligibility; @Indexed private LocalDate applicationDeadline; @Indexed private InternshipStatus status; private Instant createdAt; private Instant updatedAt;
 public Long getId(){return id;} public void setId(Long v){id=v;} public Long getCompanyId(){return companyId;} public CompanyProfile getCompany(){return company;} public void setCompany(CompanyProfile v){company=v;companyId=v==null?null:v.getId();} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getWorkMode(){return workMode;} public void setWorkMode(String v){workMode=v;} public String getDuration(){return duration;} public void setDuration(String v){duration=v;} public BigDecimal getStipendAmount(){return stipendAmount;} public void setStipendAmount(BigDecimal v){stipendAmount=v;} public String getStipendCurrency(){return stipendCurrency;} public void setStipendCurrency(String v){stipendCurrency=v;} public List<String> getSkills(){return skills;} public String getEligibility(){return eligibility;} public void setEligibility(String v){eligibility=v;} public LocalDate getApplicationDeadline(){return applicationDeadline;} public void setApplicationDeadline(LocalDate v){applicationDeadline=v;} public InternshipStatus getStatus(){return status;} public void setStatus(InternshipStatus v){status=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}
}
